#!/bin/bash
cd "$(dirname "$0")"
mkdir -p tts
say -v "?" | grep -i "vi_VN" > tts/voices.txt
V=$(grep -i -m1 -E "Linh|vi_VN" tts/voices.txt | sed -E "s/ +vi_VN.*//")
echo "Voice: $V"
say -v "$V" -r 178 -o tts/intro_0.aiff 'Chào bạn! Hôm nay mình cùng mổ xẻ một paper về AI có thể giải thích được, đăng ở hội nghị ai xi eo a hai nghìn không trăm hai mươi lăm.'
say -v "$V" -r 178 -o tts/intro_1.aiff 'Tên paper là Sparse Feature Circuits, tạm dịch: các mạch đặc trưng thưa.'
say -v "$V" -r 178 -o tts/intro_2.aiff 'Nghe thì đáng sợ, nhưng mình sẽ giải thích từng khái niệm một, trước khi dùng nó.'
say -v "$V" -r 178 -o tts/lm_0.aiff 'Trước hết, mô hình ngôn ngữ là gì? Đó là một chương trình đoán từ tiếp theo trong câu.'
say -v "$V" -r 178 -o tts/lm_1.aiff 'Ví dụ, sau câu: The boys near the teacher..., mô hình phải chọn giữa have và has.'
say -v "$V" -r 178 -o tts/lm_2.aiff 'Chủ ngữ là boys, số nhiều, nên đáp án đúng là have. Mô hình thường chọn đúng.'
say -v "$V" -r 178 -o tts/lm_3.aiff 'Nhưng câu hỏi là: bên trong nó đã làm gì để ra được quyết định đó?'
say -v "$V" -r 178 -o tts/lm_4.aiff 'Bên trong mô hình chỉ là hàng triệu con số chạy qua nhiều tầng. Nhìn vào đó, con người chẳng hiểu gì cả. Đây gọi là vấn đề hộp đen.'
say -v "$V" -r 178 -o tts/lm_5.aiff 'Lĩnh vực ích ây ai, hay AI giải thích được, cố gắng mở chiếc hộp đen này ra.'
say -v "$V" -r 178 -o tts/circuit_def_0.aiff 'Một cách mở hộp đen là tìm mạch, hay circuit.'
say -v "$V" -r 178 -o tts/circuit_def_1.aiff 'Mạch là một nhóm nhỏ các bộ phận bên trong mô hình, cùng các đường nối giữa chúng, đủ để giải thích một hành vi cụ thể.'
say -v "$V" -r 178 -o tts/circuit_def_2.aiff 'Giống như trong một thành phố khổng lồ, ta chỉ cần vẽ đúng những con đường mà chiếc xe đã đi qua.'
say -v "$V" -r 178 -o tts/problem_0.aiff 'Các nghiên cứu trước đây vẽ mạch bằng những bộ phận thô, như neuron hay attention head.'
say -v "$V" -r 178 -o tts/problem_1.aiff 'Vấn đề thứ nhất: một neuron thường đa nghĩa. Cùng một neuron có thể sáng lên với con mèo, với xe hơi, lẫn tiếng Pháp.'
say -v "$V" -r 178 -o tts/problem_2.aiff 'Vậy nên dù tìm ra mạch, ta vẫn không hiểu mạch đó đang làm gì.'
say -v "$V" -r 178 -o tts/problem_3.aiff 'Vấn đề thứ hai: nếu chia nhỏ ra thành đơn vị tinh hơn thì có hàng chục nghìn đơn vị. Thử từng cái một thì tốn thời gian khủng khiếp.'
say -v "$V" -r 178 -o tts/problem_4.aiff 'Paper này giải quyết cả hai vấn đề: dùng Sparse Autoencoder để có đơn vị dễ hiểu, và dùng xấp xỉ tuyến tính để tính cho nhanh.'
say -v "$V" -r 178 -o tts/vector_0.aiff 'Trước khi vào Sparse Autoencoder, mình ôn nhanh khái niệm vector.'
say -v "$V" -r 178 -o tts/vector_1.aiff 'Vector đơn giản là một danh sách các con số. Với hai con số, ta vẽ nó thành một mũi tên trên mặt phẳng.'
say -v "$V" -r 178 -o tts/vector_2.aiff 'Hai vector có thể cộng lại: đặt mũi tên nối đuôi nhau, ta được một mũi tên mới.'
say -v "$V" -r 178 -o tts/vector_3.aiff 'Và ta có thể nhân vector với một số, gọi là hệ số, để kéo dài hoặc thu ngắn nó.'
say -v "$V" -r 178 -o tts/vector_4.aiff 'Trong mô hình ngôn ngữ, trạng thái bên trong tại mỗi từ là một vector rất dài, gọi là activation, ký hiệu x. Với Pythia, nó có 512 con số.'
say -v "$V" -r 178 -o tts/sae_0.aiff 'Ý tưởng của Sparse Autoencoder, viết tắt là ét a e, như sau.'
say -v "$V" -r 178 -o tts/sae_1.aiff 'Ta chuẩn bị sẵn một cuốn từ điển gồm rất nhiều vector hướng, mỗi hướng là một feature, hay đặc trưng, ký hiệu v i.'
say -v "$V" -r 178 -o tts/sae_2.aiff 'Rồi ta biểu diễn activation x thành tổng của một vài feature, mỗi cái nhân với một hệ số f i.'
say -v "$V" -r 178 -o tts/sae_3.aiff 'Chữ sparse, nghĩa là thưa, tức là hầu hết hệ số bằng 0. Mỗi lần chỉ vài feature được bật lên.'
say -v "$V" -r 178 -o tts/sae_4.aiff 'Viết thành công thức: x bằng tổng các f i nhân v i, cộng b, cộng epsilon.'
say -v "$V" -r 178 -o tts/sae_5.aiff 'Ký hiệu Sigma nghĩa là cộng dồn qua tất cả các feature. b là độ lệch cố định. Còn epsilon là phần sai số mà từ điển chưa diễn tả được.'
say -v "$V" -r 178 -o tts/sae_6.aiff 'Điều kỳ diệu là các feature này thường dễ hiểu với con người, ví dụ: feature bật lên khi gặp danh từ số nhiều.'
say -v "$V" -r 178 -o tts/sae_train_0.aiff 'ét a e học cuốn từ điển đó bằng cách tối ưu hai mục tiêu cùng lúc.'
say -v "$V" -r 178 -o tts/sae_train_1.aiff 'Mục tiêu một: bản tái tạo x mũ phải gần với x thật, tức là sai số bình phương nhỏ.'
say -v "$V" -r 178 -o tts/sae_train_2.aiff 'Mục tiêu hai: phạt việc dùng quá nhiều feature, để các hệ số f i luôn thưa.'
say -v "$V" -r 178 -o tts/sae_train_3.aiff 'Từ điển rất rộng: với Pythia, số feature gấp 64 lần số chiều. Với Gemma 2, tác giả dùng bộ ét a e có sẵn tên Gemma Scope.'
say -v "$V" -r 178 -o tts/graph_0.aiff 'Và đây là mẹo quan trọng đầu tiên của paper.'
say -v "$V" -r 178 -o tts/graph_1.aiff 'Ta chèn ét a e vào nhiều vị trí trong mô hình: attention, em eo pi và dòng residual ở mỗi tầng.'
say -v "$V" -r 178 -o tts/graph_2.aiff 'Khi đó, mỗi feature, và cả phần sai số epsilon, trở thành một nút trong đồ thị tính toán. Hình vuông là feature, hình tam giác là sai số.'
say -v "$V" -r 178 -o tts/graph_3.aiff 'Việc tìm mạch bây giờ chỉ là: chọn ra những nút và cạnh quan trọng nhất trong đồ thị này.'
say -v "$V" -r 178 -o tts/metric_0.aiff 'Nhưng quan trọng với cái gì? Ta cần một thước đo, ký hiệu m.'
say -v "$V" -r 178 -o tts/metric_1.aiff 'Mô hình gán cho mỗi từ một xác suất. Ta lấy log xác suất của have trừ đi log xác suất của has.'
say -v "$V" -r 178 -o tts/metric_2.aiff 'Nếu m dương và lớn, mô hình nghiêng mạnh về have. Nếu âm, nó nghiêng về has.'
say -v "$V" -r 178 -o tts/metric_3.aiff 'Log chỉ là một cách co giãn thang đo cho dễ so sánh, bạn không cần lo về nó.'
say -v "$V" -r 178 -o tts/ie_0.aiff 'Để đo tầm quan trọng của một nút a, paper dùng khái niệm hiệu ứng gián tiếp, gọi tắt là ai i.'
say -v "$V" -r 178 -o tts/ie_1.aiff 'Ta có hai câu gần giống nhau: câu sạch, The teacher, và câu vá, The teachers. Chỉ khác số ít, số nhiều.'
say -v "$V" -r 178 -o tts/ie_2.aiff 'Chạy mô hình trên câu sạch. Rồi, đúng tại nút a, ta thay giá trị của nó bằng giá trị lấy từ câu vá. Ký hiệu do nghĩa là: ép nút này nhận giá trị đó.'
say -v "$V" -r 178 -o tts/ie_3.aiff 'ai i bằng thước đo m sau khi can thiệp, trừ đi m ban đầu. Nếu m thay đổi nhiều, nút a thật sự có ảnh hưởng.'
say -v "$V" -r 178 -o tts/ie_4.aiff 'Đây là suy luận nhân quả: ta không chỉ nhìn tương quan, mà thật sự can thiệp và xem kết quả thay đổi.'
say -v "$V" -r 178 -o tts/cost_0.aiff 'Vấn đề là: làm như vậy thì mỗi nút cần chạy lại cả mô hình một lần.'
say -v "$V" -r 178 -o tts/cost_1.aiff 'Với hàng chục nghìn feature ở nhiều vị trí, việc này quá chậm.'
say -v "$V" -r 178 -o tts/atp_0.aiff 'Giải pháp là xấp xỉ tuyến tính, dùng gradient. Gradient nghĩa là độ dốc: nếu nhích a một chút, m thay đổi bao nhiêu.'
say -v "$V" -r 178 -o tts/atp_1.aiff 'Hãy tưởng tượng m là một đường cong theo a. Tại điểm sạch, ta vẽ đường tiếp tuyến.'
say -v "$V" -r 178 -o tts/atp_2.aiff 'Thay vì thật sự đi tới điểm vá, ta đi dọc theo tiếp tuyến: độ dốc nhân với khoảng cách, là ra ước lượng.'
say -v "$V" -r 178 -o tts/atp_3.aiff 'Đó là công thức attribution patching: ai i xấp xỉ bằng gradient của m theo a, nhân với a vá trừ a sạch.'
say -v "$V" -r 178 -o tts/atp_4.aiff 'Cái hay: chỉ cần hai lượt chạy xuôi và một lượt lan truyền ngược, ta có ước lượng cho tất cả các nút cùng lúc.'
say -v "$V" -r 178 -o tts/atp_5.aiff 'Lan truyền ngược, hay backpropagation, là thuật toán tính gradient cho mọi nút chỉ trong một lần.'
say -v "$V" -r 178 -o tts/ig_0.aiff 'Nhưng nếu đường cong uốn mạnh, tiếp tuyến sẽ đoán sai, nhất là ở các tầng đầu của mô hình.'
say -v "$V" -r 178 -o tts/ig_1.aiff 'Khi đó paper dùng integrated gradients, tức là gradient tích phân.'
say -v "$V" -r 178 -o tts/ig_2.aiff 'Ta chia đoạn từ a sạch tới a vá thành 10 bước, đo độ dốc tại mỗi bước, rồi lấy trung bình.'
say -v "$V" -r 178 -o tts/ig_3.aiff 'Độ dốc trung bình này bám theo đường cong tốt hơn nhiều, đổi lại tốn thêm khoảng 10 lần tính toán.'
say -v "$V" -r 178 -o tts/filter_0.aiff 'Có điểm ai i cho mọi nút rồi, ta lấy trung bình trên nhiều cặp câu.'
say -v "$V" -r 178 -o tts/filter_1.aiff 'Sau đó giữ lại những nút có độ lớn ai i vượt ngưỡng tê en. Các nút còn lại bị bỏ đi.'
say -v "$V" -r 178 -o tts/filter_2.aiff 'Làm tương tự với các cạnh nối giữa các nút, dùng ngưỡng tê i.'
say -v "$V" -r 178 -o tts/filter_3.aiff 'Kết quả là một đồ thị nhỏ gọn: một mạch đặc trưng thưa, gồm các feature dễ hiểu và cách chúng truyền thông tin cho nhau.'
say -v "$V" -r 178 -o tts/pipeline_0.aiff 'Tóm lại, quy trình có bốn bước.'
say -v "$V" -r 178 -o tts/pipeline_1.aiff 'Bước một: chạy mô hình trên câu sạch và câu vá, lưu lại mọi activation.'
say -v "$V" -r 178 -o tts/pipeline_2.aiff 'Bước hai: lan truyền ngược, lưu gradient của m tại mọi nút.'
say -v "$V" -r 178 -o tts/pipeline_3.aiff 'Bước ba: tính ai i xấp xỉ cho từng nút, lọc theo ngưỡng.'
say -v "$V" -r 178 -o tts/pipeline_4.aiff 'Bước bốn: tính ai i cho các cạnh, lọc tiếp. Và ta có mạch.'
say -v "$V" -r 178 -o tts/eval_0.aiff 'Làm sao biết mạch này tốt? Paper dùng hai thước đo.'
say -v "$V" -r 178 -o tts/eval_1.aiff 'Thứ nhất là độ trung thành, faithfulness. Ta chỉ giữ lại mạch C, còn mọi nút khác bị thay bằng giá trị trung bình. Gọi là mean ablation.'
say -v "$V" -r 178 -o tts/eval_2.aiff 'Faithfulness bằng m của mạch trừ m của mạch rỗng, chia cho m của cả mô hình trừ m của mạch rỗng. Tức là: mạch giải thích được bao nhiêu phần trăm hành vi. Lý tưởng là 1.'
say -v "$V" -r 178 -o tts/eval_3.aiff 'Thứ hai là độ đầy đủ, completeness: bỏ mạch đi, xem phần còn lại còn làm được việc không. Lý tưởng là gần 0.'
say -v "$V" -r 178 -o tts/eval_4.aiff 'Kết quả: trên Pythia, chỉ khoảng 100 feature đã giải thích phần lớn hành vi, trong khi cần khoảng 1500 neuron mới giải thích được một nửa.'
say -v "$V" -r 178 -o tts/eval_5.aiff 'Trên Gemma 2, khoảng 500 feature so với khoảng 50 nghìn neuron. Feature hiệu quả hơn hẳn.'
say -v "$V" -r 178 -o tts/case_0.aiff 'Giờ ta xem một mạch cụ thể: hòa hợp chủ ngữ và động từ qua mệnh đề quan hệ.'
say -v "$V" -r 178 -o tts/case_1.aiff 'Câu mẫu: The girl that the teacher sees, rồi đến has hoặc have. Chú ý: động từ phải hợp với girl, không phải teacher.'
say -v "$V" -r 178 -o tts/case_2.aiff 'Đầu tiên, các feature ở tầng thấp phát hiện số ít hay số nhiều của danh từ girl.'
say -v "$V" -r 178 -o tts/case_3.aiff 'Tiếp theo, các feature nhận ra từ that đang mở đầu một mệnh đề phụ.'
say -v "$V" -r 178 -o tts/case_4.aiff 'Rồi các feature phát hiện mệnh đề phụ đã kết thúc, và mang thông tin số của chủ ngữ tới vị trí cuối.'
say -v "$V" -r 178 -o tts/case_5.aiff 'Cuối cùng, các feature phân biệt dạng động từ đẩy xác suất về has hoặc have.'
say -v "$V" -r 178 -o tts/case_6.aiff 'Mạch này đọc được như một thuật toán mà con người hiểu. Gemma 2 còn dùng thêm các feature theo dõi số của cả cụm danh từ.'
say -v "$V" -r 178 -o tts/shift_problem_0.aiff 'Phần ứng dụng thú vị nhất: Shift, tức là cắt tỉa các feature giả tạo mà con người hiểu được.'
say -v "$V" -r 178 -o tts/shift_problem_1.aiff 'Bài toán: phân loại nghề nghiệp từ tiểu sử, giáo sư hay y tá.'
say -v "$V" -r 178 -o tts/shift_problem_2.aiff 'Nhưng dữ liệu huấn luyện bị lệch cực độ: toàn giáo sư nam và y tá nữ.'
say -v "$V" -r 178 -o tts/shift_problem_3.aiff 'Mô hình sẽ đi đường tắt: đoán theo giới tính thay vì nghề nghiệp. Đó là tín hiệu giả, spurious signal.'
say -v "$V" -r 178 -o tts/shift_problem_4.aiff 'Các phương pháp cũ cần thêm dữ liệu có nhãn để gỡ lệch. Ở đây, ta không có dữ liệu đó.'
say -v "$V" -r 178 -o tts/shift_method_0.aiff 'Shift làm như sau. Bước một: tìm mạch đặc trưng giải thích quyết định của bộ phân loại.'
say -v "$V" -r 178 -o tts/shift_method_1.aiff 'Bước hai: con người đọc từng feature trong mạch, và đánh giá nó có liên quan đến nghề nghiệp hay không.'
say -v "$V" -r 178 -o tts/shift_method_2.aiff 'Ví dụ, feature bật lên với từ she, her, hay women là về giới tính, không liên quan tới nghề.'
say -v "$V" -r 178 -o tts/shift_method_3.aiff 'Bước ba: tắt hẳn các feature không liên quan, bằng cách đặt chúng về 0. Bước bốn, tùy chọn: huấn luyện lại lớp phân loại.'
say -v "$V" -r 178 -o tts/shift_result_0.aiff 'Kết quả trên Pythia, đo trên dữ liệu cân bằng.'
say -v "$V" -r 178 -o tts/shift_result_1.aiff 'Độ chính xác đoán nghề tăng từ 62 phần trăm lên 88, và lên 93 sau khi huấn luyện lại, ngang với mô hình lý tưởng.'
say -v "$V" -r 178 -o tts/shift_result_2.aiff 'Khả năng đoán giới tính giảm từ 87 xuống khoảng 52 phần trăm, gần như đoán mò. Nghĩa là thiên kiến giới tính đã gần như biến mất.'
say -v "$V" -r 178 -o tts/shift_result_3.aiff 'Nhóm tệ nhất tăng từ 24 lên 89 phần trăm. Còn nếu tắt feature ngẫu nhiên, hay dùng neuron, thì không đạt được như vậy.'
say -v "$V" -r 178 -o tts/unsup_0.aiff 'Cuối cùng, paper tự động hóa toàn bộ quy trình ở quy mô lớn.'
say -v "$V" -r 178 -o tts/unsup_1.aiff 'Lấy một kho văn bản khổng lồ, gom các ví dụ có cách dự đoán giống nhau thành từng cụm, không cần con người gán nhãn.'
say -v "$V" -r 178 -o tts/unsup_2.aiff 'Mỗi cụm là một hành vi, ví dụ: đếm tiếp dãy số một, hai, ba, bốn, hoặc dự đoán từ to sau các động từ.'
say -v "$V" -r 178 -o tts/unsup_3.aiff 'Rồi tìm mạch cho từng cụm. Kết quả là hàng nghìn mạch cho hàng nghìn hành vi, có thể xem tại trang feature circuits chấm ích i dét.'
say -v "$V" -r 178 -o tts/limits_0.aiff 'Tất nhiên, phương pháp vẫn có hạn chế.'
say -v "$V" -r 178 -o tts/limits_1.aiff 'Cần có ét a e được huấn luyện sẵn, tốn nhiều tài nguyên tính toán ban đầu.'
say -v "$V" -r 178 -o tts/limits_2.aiff 'Phần sai số epsilon vẫn là hộp đen nhỏ chưa giải thích được.'
